{
  "analysis": "QEMU installation completed successfully (version 8.2.2 from Ubuntu 24.04). Now we need to: 1) verify QEMU binaries, 2) launch QEMU with snapshot mode, VNC :1, and monitor socket, 3) start websockify to bridge VNC to WebSocket, 4) configure nginx on port 80 to serve noVNC and proxy to websockify, and 5) verify everything is running and the VM is booting.",
  "plan": "Verify QEMU is installed, then launch QEMU in daemonized mode with all required options. Start websockify as a daemon bridging localhost:5901 to localhost:6080. Create an nginx configuration to serve noVNC on port 80 and proxy WebSocket connections to websockify. Restart nginx, then verify all services and the monitor socket are functional.",
  "commands": [
    {
      "keystrokes": "qemu-system-i386 --version | head -2
",
      "duration": 0.1
    },
    {
      "keystrokes": "rm -f /tmp/qemu-monitor.sock
qemu-system-i386 \
  -hda /app/isos/win311.img \
  -snapshot \
  -m 32 \
  -vnc :1 \
  -monitor unix:/tmp/qemu-monitor.sock,server,nowait \
  -daemonize \
  -pidfile /tmp/qemu.pid
",
      "duration": 1.0
    },
    {
      "keystrokes": "websockify -D --web=/usr/share/novnc 127.0.0.1:6080 127.0.0.1:5901
",
      "duration": 1.0
    },
    {
      "keystrokes": "cat > /etc/nginx/sites-available/novnc << 'EOF'
server {
    listen 80 default_server;
    server_name _;

    location / {
        root /usr/share/novnc;
        index vnc.html vnc_lite.html;
    }

    location /websockify {
        proxy_pass http://127.0.0.1:6080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/novnc /etc/nginx/sites-enabled/novnc
nginx -t && nginx -s reload 2>/dev/null || nginx
",
      "duration": 0.1
    },
    {
      "keystrokes": "echo "=== QEMU PID ==="; cat /tmp/qemu.pid 2>/dev/null; echo; echo "=== QEMU process ==="; ps aux | grep qemu-system | grep -v grep; echo "=== Monitor socket ==="; ls -la /tmp/qemu-monitor.sock; echo "=== Listening ports ==="; ss -tlnp | grep -E ':80|:5901|:6080'; echo "=== Monitor test ==="; echo 'info status' | socat - UNIX-CONNECT:/tmp/qemu-monitor.sock 2>/dev/null || echo 'socat not found, trying python'; python3 -c "import socket; s=socket.socket(socket.AF_UNIX); s.connect('/tmp/qemu-monitor.sock'); s.sendall(b'info status\n'); print(s.recv(4096).decode(errors='replace')); s.close()"
",
      "duration": 0.1
    }
  ]
}
